const I18N = {
  lang: (() => { try { return localStorage.getItem("onsite.lang") || "en"; } catch { return "en"; } })(),
  t(key, vars = {}) {
    let s = (STRINGS[this.lang] && STRINGS[this.lang][key]) ?? STRINGS.en[key] ?? key;
    for (const [k, v] of Object.entries(vars)) s = s.replaceAll(`{${k}}`, v);
    return s;
  },
  set(lang) {
    this.lang = lang;
    try { localStorage.setItem("onsite.lang", lang); } catch {}
    this.apply();
  },
  apply() {
    document.documentElement.lang = this.lang;
    document.documentElement.dir = this.lang === "ar" ? "rtl" : "ltr";
  },
  subjectName(s) { return s ? (this.lang === "ar" ? s.name_ar : s.name_en) : ""; },
};
const t = (k, v) => I18N.t(k, v);
I18N.apply();
